SELECT *
FROM shopwizard.tCmpSupplyCompNotice

    AND NoticeNo = #{pNoticeNo}


        AND (RegistDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d')
        AND RegistDate <  ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY))



         AND StartDate <= CURDATE() AND EndDate >= CURDATE() 



    ORDER BY ${sidx} ${sord}
    ORDER BY NoticeNo DESC

LIMIT #{topCnt}, #{countPerPage}

SELECT Cntnts
FROM shopwizard.tCmpSupplyCompNotice
WHERE NoticeNo = #{value}
